</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const md5 = useMd5();
const num = ref(3)
const tits = ref('新增代理')

const props = defineProps(['id'])
// Refs
const formNameRef = ref(null)
const users = ref(false)
const codes = ref(false)
const copy_id = ref('')
const proxy_id = ref('')
const isIOpen = ref(true)
const errorText = ref('')
const logInfo = ref('')

const waterOtions = [
    { value: 0, label: '水全退到底' },
    { value: 0.1, label: '赚取0.1%退水' },
    { value: 0.3, label: '赚取0.3%退水' },
    { value: 0.5, label: '赚取0.5%退水' },
    { value: 1.0, label: '赚取1.0%退水' },
    { value: 1.5, label: '赚取1.5%退水' },
    { value: 2.0, label: '赚取2.0%退水' },
    { value: 2.5, label: '赚取2.5%退水' },
    { value: 99, label: '赚取所有退水' },
]

const value = ref(0)

const userInfo = ref({
    handicapList: [],
    menuList: [],
    lotteryList: [],
    occupyList: [],
    role: 0,
    layer: 0,
    account: '',
    cash: 0,
    cashUsed: 0,
    searchUrl: '',
    searchCode: '',
    id: ''
})
const lotterylist = ref([])
const LotteryTypeList = ref([])

const ruleForm = reactive({
    listIp: [{ id: 1, ip: '' }],
    account: '',
    nickName: '',
    companyName: '',
    name: '',
    passwd: '',
    secound: '',
    status: 1,
    ownReback: '',
    mode: 1,
    cash: '',
    breakStatus: 0,
    occupyList: [],
    handicapList: [],
    menuList: [],
    lotlist: [],
    lotteryList: [],
    opcpList: [],
    whiteIp: '',
    auto_odds: 0,
    manual_odds: 0,
    member_odds: 0,
    money_odds: 0,
    isOpen: 2,
    finalOdds: 0,
    maxOccupy: '',
    minShare: '',
    maxShare: '',
    repFlag: 2,
    pid: '',
    password: '',
    secoundPassword: '',
    replenishOpen: [],
    role: 0,
    copyId: ''
})

// Computed
const cash2china = computed(() => {
    if (ruleForm.cash * 1 > 0) {
        return nzhcn.encodeS(ruleForm.cash)
    }
    return ''
})

const copyText = computed(() => {
    return `导航:${userInfo.value.searchUrl}\n安全码:${userInfo.value.searchCode}\n账号:${ruleForm.account}\n密码:${ruleForm.passwd}`
})
// 验证器函数
const createMinMaxValidator = (ruleFormRef, ruleFormName) => (rule, value, callback) => {
    let tt = rule.field.split('.')
    let t1 = ruleFormRef[ruleFormName][tt[1]]?.pminShare
    let t2 = ruleFormRef[ruleFormName][tt[1]]?.pmaxShare
    if (value < t1) {
        callback(new Error('填写的值不能小于最低值!'))
    } else if (value > t2) {
        callback(new Error('填写的值不能大于最高值!'))
    } else {
        callback()
    }
}

const createMinValidator = (ruleFormRef, ruleFormName) => (rule, value, callback) => {
    let tt = rule.field.split('.')
    let t2 = ruleFormRef[ruleFormName][tt[1]]?.pmaxShare
    if (value < 0) {
        callback(new Error('填写的值不能小于最低值!'))
    } else if (value > t2) {
        callback(new Error('填写的值不能大于最高值!'))
    } else {
        callback()
    }
}

const createMaxValidator = (ruleFormRef, ruleFormName) => (rule, value, callback) => {
    let tt = rule.field.split('.')
    let t2 = ruleFormRef[ruleFormName][tt[1]]?.pmaxShare
    let t3 = ruleFormRef[ruleFormName][tt[1]]?.minShare
    if (value < 0) {
        callback(new Error('填写的值不能小于最低值!'))
    } else if (value > t2) {
        callback(new Error('填写的值不能大于最高值!'))
    } else if (value < t3) {
        callback(new Error('输入最大值不能小于输入最小值!'))
    } else {
        callback()
    }
}

const createMoneyValidator = (userInfoRef, field) => (value) => {
    if (userInfoRef.value[field] == 0 || userInfoRef.value[field] > 0) {
        if (value > userInfoRef.value[field]) {
            return false
        } else {
            return true
        }
    }
    return true
}

// Rules
const rules = reactive({
    account: [
        { required: true, message: '请填写账户', trigger: 'blur' },
        { type: 'string', pattern: /^[\w\d-]{4,}$/, message: '账号使用英文字符、数字4位以上', trigger: 'blur' },
        { min: 4, message: '账户最小4个字符', trigger: 'blur' },
    ],
    passwd: [
        { required: true, message: '请填写登录密码', trigger: 'blur' },
        {
            type: 'string',
            pattern: /(?![^a-zA-Z0-9]+$)(?![^a-zA-Z/D]+$)(?![^0-9/D]+$).{6,20}$/,
            message: '密码由6位以上英文、数字组成',
            trigger: 'blur'
        },
    ],
    cash: [
        { type: 'number', min: 1, message: '现金额度只能是数字', trigger: 'blur' },
        { validator: createMoneyValidator(userInfo, 'cash'), message: '不能超出上级余额!', trigger: 'blur' }
    ],
    handicapList: [
        { type: 'array', required: true, message: '请选择开放盘口', trigger: 'change' }
    ],
    ownReback: [
        { required: true, message: '请填写退水', trigger: 'blur' },
        { type: 'number', min: 0, message: '退水只能是数字', trigger: 'change' },
        { type: 'number', min: 0, message: '退水只能是数字', trigger: 'blur' },
    ]
})

// Methods
const onCopy = (e) => {
    console.log(e)
}

const onError = (e) => {
    alert("失败")
}

const copyOccupy = (num) => {
    switch (num) {
        case 1:
            ruleForm.opcpList.forEach(iten => {
                iten.maxOccupy = ruleForm.maxOccupy
            })
            break
        case 2:
            ruleForm.opcpList.forEach(iten => {
                iten.minShare = ruleForm.minShare
            })
            break
        case 3:
            ruleForm.opcpList.forEach(iten => {
                iten.maxShare = ruleForm.maxShare
            })
            break
        case 4:
            ruleForm.opcpList.forEach(iten => {
                if (iten.prepFlag == 1) {
                    iten.repFlag = ruleForm.repFlag
                }
            })
            break
    }
}

const check_count = (e) => {
    let obj = e.target
    if (obj.value != '' && obj.value.substr(0, 1) == '.') {
        obj.value = ""
    }
    let result = (obj.value.toString()).indexOf(".")
    if (result != -1) {
        obj.value = ""
    }
    obj.value = obj.value.replace(/\D/g, '')
}

const deleAcout = (index) => {
    ruleForm.listIp.splice(index, 1)
}

const addAcout = () => {
    if (ruleForm.listIp.length < 10) {
        ruleForm.listIp.push({ ip: "" })
    } else {
        showToast({
            message: '最多只能新增10个ip',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
    }
}

const selects = async () => {
    const reg = /^[a-zA-Z]\w{3,9}$/
    if (!ruleForm.account) return
    if (!reg.test(ruleForm.account)) {
        showToast({
            message: '请输入正确账号首个字母为英文加数字组合，4-10位数!',
            icon: 'fail',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        ruleForm.account = ""
        return false
    }
    let username = ruleForm.account.toLowerCase()
    try {
        const data = await userStore.checkAcc(username)
        if (data.data) {
            users.value = true
            return true
        } else {
            users.value = false
            ruleForm.account = ""
            showToast({
                message: '账号已存在!',
                icon: 'fail',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return false
        }
    } catch (error) {
        console.error(error)
    }
}

const changewater = () => {
    ruleForm.ownReback = value.value
}

const selctLottry = () => {
    ruleForm.opcpList.forEach(iten => {
        if (ruleForm.lotlist.includes(parseInt(iten.lotteryId))) {
            iten.selected = true
        } else {
            iten.selected = false
        }
    })
}

const getUserInfo = async () => {
    try {
        const res = await userStore.getQueryOrg(props.id)
        userInfo.value = res.data
        lotterylist.value = res.data.lotteryList
        ruleForm.mode = res.data.mode ? res.data.mode : 1
        
        lotterylist.value.forEach(item => {
            ruleForm.lotlist.push(item.lotteryId)
        })
        
        ruleForm.handicapList = userInfo.value.handicapList
        
        if (res.data.role < 2) {
            isIOpen.value = false
        }
        
        if (logInfo.value.role == 1) {
            res.data.occupyList.forEach(iten => {
                iten.maxOccupy = 100
            })
        } else {
            res.data.occupyList.forEach(iten => {
                iten.pmaxOccupy = iten.maxOccupy
                iten.pmaxShare = iten.maxShare
                iten.pminShare = iten.minShare
                iten.maxOccupy = '0'
                iten.maxShare = '0'
                iten.minShare = '0'
                iten.prepFlag = iten.repFlag
                iten.repFlag = 2
                iten.selected = true
            })
        }
        
        ruleForm.opcpList = res.data.occupyList
        
        if (userInfo.value.menuList.length > 0) {
            for (let j = 0; j < userInfo.value.menuList.length; j++) {
                if (userInfo.value.menuList[j] == 1) {
                    isIOpen.value = false
                }
            }
        }
        
        // 动态添加 rules 中的验证器
        rules.upper_hold = [
            { type: 'number', message: '只能填写数字', trigger: 'blur' },
            { required: true, message: '请填写最高占成', trigger: 'blur' },
            { validator: createMinMaxValidator(ruleForm, 'opcpList'), trigger: 'blur' }
        ]
        rules.min_hold = [
            { type: 'number', min: 0, message: '只能填写数字', trigger: 'blur' },
            { required: true, message: '请填写最低占成', trigger: 'blur' },
            { validator: createMinValidator(ruleForm, 'opcpList'), trigger: 'blur' }
        ]
        rules.max_hold = [
            { type: 'number', min: 0, message: '只能填写数字', trigger: 'blur' },
            { required: true, message: '请填写最高占成', trigger: 'blur' },
            { validator: createMaxValidator(ruleForm, 'opcpList'), trigger: 'blur' }
        ]
    } catch (error) {
        console.error(error)
    }
}

const onSubmit = async () => {
    if (!ruleForm.passwd) {
        showToast({
            message: '密码不能为空值!',
            icon: 'fail',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        return false
    }
    
    if (userInfo.value.role == 2) {
        if (ruleForm.companyName && ruleForm.name) {
            ruleForm.nickName = ruleForm.companyName + '_' + ruleForm.name
        } else {
            showToast({
                message: '昵称和分公司名称必须填写!',
                icon: 'fail',
                className: 'custom-toast',
                duration: 2000  // 自定义显示时间
            });
            return false
        }
    }
    
    await addProxy()
}

const addProxy = async () => {
    const loading = showLoadingToast({
        lock: true,
        duration: 0,
        forbidClick: true,
        mask: true,
        background: 'rgba(0, 0, 0, 0.7)',
        message: '正在加载……'
    })
    
    ruleForm.pid = props.id
    ruleForm.occupyList = []
    ruleForm.replenishOpen = []
    ruleForm.lotteryList = []
    
    lotterylist.value.forEach(item => {
        ruleForm.lotlist.forEach(items => {
            if (item.lotteryId == items) {
                ruleForm.lotteryList.push(item)
            }
        })
    })
    
    if (userInfo.value.role == 1) {
        ruleForm.role = 2
        ruleForm.menuList = [7, 8, 9, 42]
    } else if (userInfo.value.role > 1) {
        ruleForm.role = 3
    }
    
    let ips = ''
    ruleForm.listIp.forEach(its => {
        if (its.ip) {
            ips += its.ip + ','
        }
    })
    if (ips) {
        ips = ips.substring(0, ips.length - 1)
    }
    ruleForm.whiteIp = ips
    ruleForm.copyId = proxy_id.value
    
    let paw = ruleForm.passwd.toLowerCase()
    let pass =md5(paw)
    ruleForm.password = pass
    
    if (ruleForm.secound) {
        let paw1 = ruleForm.secound.toLowerCase()
        let sendpass = md5(paw1)
        ruleForm.secoundPassword = sendpass
    }
    
    let t = ''
    let tt = []
    ruleForm.opcpList.forEach(iten => {
        if (iten.repFlag == 1) {
            ruleForm.replenishOpen.push(iten.lotteryId)
        }
        if (iten.selected) {
            tt.push(iten)
        }
        if (iten.maxOccupy < iten.pminShare || iten.maxOccupy > iten.pmaxShare || 
            iten.minShare > iten.maxShare || iten.minShare > iten.pmaxShare || 
            iten.maxShare > iten.pmaxShare) {
            t = 1
            return false
        }
    })
    
    if (t) {
        showToast({
            message: '上级占成不能超过最大值或者最低值不能超过最高值!',
            icon: 'fail',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        loading.close()
        return false
    }
    
    ruleForm.occupyList = tt
    
    if (ruleForm.isOpen == 1) {
        ruleForm.menuList.push(1)
    }
    
    if (userInfo.value.role == 2) {
        if (ruleForm.finalOdds == 1) {
            ruleForm.menuList.push(2)
        }
        if (ruleForm.breakStatus == 1) {
            ruleForm.menuList.push(3)
        }
        if (ruleForm.auto_odds == 1) {
            ruleForm.menuList.push(13)
        }
        if (ruleForm.manual_odds == 1) {
            ruleForm.menuList.push(15)
        }
        if (ruleForm.money_odds == 1) {
            ruleForm.menuList.push(11)
        }
        if (ruleForm.member_odds == 1) {
            ruleForm.menuList.push(12)
        }
    }
    
    ruleForm.ownReback = ruleForm.ownReback > 0 ? ruleForm.ownReback : 0
    ruleForm.cash = ruleForm.cash > 0 ? ruleForm.cash : 0
    
    setTimeout(() => {
        loading.close()
    }, 3000)
    
    try {
        const res = await userStore.orgAdd(ruleForm)
        loading.close()
        showToast({
            message: '操作成功',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        if (res.code == 200) {
            if (userInfo.value.role == 1) {
                router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
            } else {
                if (res.data != '成功') {
                    showConfirmDialog({
                        message: '是否设置退水信息。',
                        title: '提示',
                        confirmButtonText: '是',
                        cancelButtonText: '否',
                    }).then(() => {
                        if (userInfo.value.role == 2) {
                            router.push({ path: '/oddsSet/' + res.data })
                        } else {
                            router.push({ path: '/RefundWater/' + res.data })
                        }
                    }).catch(() => {
                        router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
                    })
                } else {
                    router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
                }
            }
        }
    } catch (error) {
        console.error(error)
    }
}

const cancelForm = () => {
    router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
}

onMounted(() => {
    let ust = JSON.parse(localStorage.getItem('userInfo'))
    logInfo.value = ust
    getUserInfo()
})
</script>

